#!/usr/bin/env python3
from pathlib import Path
import argparse, base64, json, subprocess, sys

APP_NAME = "C11-C Studio"
APP_VERSION = "0.2.3"
DEFAULT_TARGET = Path.cwd() / "c11c-studio"
FILES_B64 = {'main.py': '', 'requirements.txt': 'UHlTaWRlNj49Ni42LDw3Cg==', 'BUILD_MANIFEST.json': '', 'devcheck.py': '', 'self_test.py': '', 'README.md': '', 'run.bat': '', 'c11c_studio/__init__.py': 'X192ZXJzaW9uX18gPSAiMC4yLjMiCg==', 'docs/C11C_STUDIO_SUPER_PROMPT_PRINCIPAL_DEVELOPER_v2.1.4.md': '', 'docs/C11C_STUDIO_BUILD_NOTES_v0.2.3.md': '', 'docs/C11C_STUDIO_BUILD_NOTES_v0.2.2.md': '', 'docs/C11C_STUDIO_FIRST_BUILD_AUDIT_v0.2.1.md': '', 'docs/C11C_STUDIO_MASTER_SPEC_v2.1.4_FULL_CONFIGURATION.md': '', 'c11c_studio/ui/__init__.py': '', 'c11c_studio/ui/theme.py': '', 'c11c_studio/ui/main_window.py': '', 'c11c_studio/services/job_manager.py': '', 'c11c_studio/services/environment_validator.py': '', 'c11c_studio/services/__init__.py': '', 'c11c_studio/services/seed_manager.py': '', 'c11c_studio/services/artifact_registry.py': '', 'c11c_studio/services/product_catalog.py': '', 'c11c_studio/services/command_builder.py': '', 'c11c_studio/services/tool_discovery.py': '', 'c11c_studio/services/snapshot.py': '', 'c11c_studio/services/log_parser.py': '', 'c11c_studio/services/introspection.py': '', 'c11c_studio/services/family_registry.py': '', 'c11c_studio/domain/job.py': '', 'c11c_studio/domain/__init__.py': '', 'c11c_studio/domain/seed.py': '', 'c11c_studio/domain/parameter.py': '', 'c11c_studio/domain/family.py': '', 'c11c_studio/domain/product.py': '', 'c11c_studio/core/config.py': '', 'c11c_studio/core/project_context.py': '', 'c11c_studio/core/__init__.py': '', 'c11c_studio/core/paths.py': '', 'c11c_studio/ui/widgets/__init__.py': '', 'c11c_studio/ui/widgets/nav_button.py': '', 'c11c_studio/ui/widgets/log_view.py': '', 'c11c_studio/ui/widgets/status_card.py': '', 'c11c_studio/ui/pages/reproduction.py': '', 'c11c_studio/ui/pages/review.py': '', 'c11c_studio/ui/pages/art_direction.py': '', 'c11c_studio/ui/pages/__init__.py': '', 'c11c_studio/ui/pages/jobs.py': '', 'c11c_studio/ui/pages/validation.py': '', 'c11c_studio/ui/pages/products.py': '', 'c11c_studio/ui/pages/seeds.py': '', 'c11c_studio/ui/pages/artifacts.py': '', 'c11c_studio/ui/pages/games.py': '', 'c11c_studio/ui/pages/logs.py': '', 'c11c_studio/ui/pages/production.py': '', 'c11c_studio/ui/pages/settings.py': '', 'c11c_studio/ui/pages/dashboard.py': '', 'c11c_studio/ui/pages/families.py': '', 'c11c_studio/ui/pages/about.py': ''}

def write_project(target: Path):
    target = target.resolve()
    target.mkdir(parents=True, exist_ok=True)
    old_manifest = target / "BUILD_MANIFEST.json"
    old_owned = []
    if old_manifest.exists():
        try:
            data = json.loads(old_manifest.read_text(encoding="utf-8-sig"))
            old_owned = list(data.get("owned_files", []))
        except (OSError, ValueError, TypeError):
            old_owned = []
    new_owned = set(FILES_B64)
    for rel in old_owned:
        if rel not in new_owned:
            p = target / rel
            if p.is_file():
                p.unlink()
    for rel, data in FILES_B64.items():
        p = target / Path(rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(data))
    print(f"[{APP_NAME}] v{APP_VERSION} written to: {target}")
    return target

def install_and_run(target: Path, project=None):
    venv = target / ".venv"
    if not venv.exists():
        r = subprocess.run([sys.executable, "-m", "venv", str(venv)], check=False)
        if r.returncode:
            return r.returncode
    py = venv / ("Scripts/python.exe" if sys.platform.startswith("win") else "bin/python")
    r = subprocess.run([str(py), "-m", "pip", "install", "-r", str(target / "requirements.txt")], check=False)
    if r.returncode:
        return r.returncode
    cmd = [str(py), str(target / "main.py")]
    if project:
        cmd += ["--project", str(Path(project).resolve())]
    return subprocess.call(cmd)

def main():
    ap = argparse.ArgumentParser(prog="bootstrap_studio.py")
    ap.add_argument("--target", default=str(DEFAULT_TARGET))
    ap.add_argument("--install", action="store_true")
    ap.add_argument("--run", action="store_true")
    ap.add_argument("--project", default=None)
    ns = ap.parse_args()
    target = write_project(Path(ns.target))
    if ns.install or ns.run:
        return install_and_run(target, ns.project)
    print("Next: run.bat [--project PATH] or python main.py --project PATH")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
